#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* next;
};

void push(Node*& head, int value) {
    Node* n = new Node();
    n->data = value;
    n->next = head;
    head = n;
}

int main() {
    Node* head = NULL;
    push(head, 20);
    push(head, 10);
    return 0;
}
